import numpy as np
g = np.array(grid)
print(g.shape)
# panels: rows of 5 (separators at 5,11,17,23), cols 7 (seps at 5,11,17)
# extract each panel, find shapes
panels={}
for r0 in range(0,26,6):
    for c0 in range(0,23,6):
        if r0+5>26 or c0+5>23: continue
        p=g[r0:r0+5,c0:c0+5]
        if (p==8).all(): continue
        nz=set(p.flatten())-{0,8}
        if nz:
            panels[(r0//6,c0//6)]=(nz.pop(),p.copy())
for k,(col,p) in sorted(panels.items()):
    print(k,col)
    print('\n'.join(''.join(str(x) for x in row) for row in p))

