out = [row[:] for row in grid]
def rot(r,c,cr,cc): return (2*cr-r, 2*cc-c)
def fill_from(cells, cr, cc, val):
    for r,c in cells:
        rr,cc2 = rot(r,c,cr,cc)
        out[rr][cc2] = val
def cells_of(color):
    res=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==color: res.append((r,c))
    return res
# color 2 block center (5,5): copy (0,0) panel shapes -> (1,1)
fill_from(cells_of(2), 5, 5, 2)
# color 1 block center (11,17): copy (2,2) shapes -> (1,3)
fill_from(cells_of(1), 11, 17, 1)
# color 4 block center (17,5): copy (2,1) shapes -> (3,0)
fill_from(cells_of(4), 17, 5, 4)
